-- Wayne's Pizza POS — Phase 8: transactional Hanafy integration outbox.
insert into public.permissions (id,code,description) values ('20000000-0000-4000-8000-000000000019','integrations.manage','View and safely replay Hanafy integration events');
insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r join public.permissions p on p.code='integrations.manage' where r.code in ('owner','manager');
create table public.integration_destinations (id text primary key default 'hanafy', endpoint_url text not null check(endpoint_url ~ '^https://'), business_id text not null default 'waynes-pizza', signing_secret text not null check(char_length(signing_secret)>=32), previous_signing_secret text, previous_secret_expires_at timestamptz, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.integration_outbox (id uuid primary key default gen_random_uuid(), event_id uuid not null default gen_random_uuid() unique, destination text not null references public.integration_destinations(id), event_type text not null check(event_type ~ '^[a-z]+(\.[a-z_]+)+$'), occurred_at timestamptz not null default now(), payload jsonb not null check(jsonb_typeof(payload)='object'), status text not null default 'pending' check(status in ('pending','processing','delivered','failed')), attempts integer not null default 0 check(attempts>=0), next_attempt_at timestamptz not null default now(), last_error text, lease_token uuid, lease_expires_at timestamptz, created_at timestamptz not null default now(), delivered_at timestamptz);
create table public.integration_delivery_logs (id uuid primary key default gen_random_uuid(), outbox_id uuid not null references public.integration_outbox(id) on delete restrict, attempt_number integer not null, request_status text not null check(request_status in ('delivered','failed')), response_code integer, response_body_truncated text, error_message text, attempted_at timestamptz not null default now(), unique(outbox_id,attempt_number));
create index integration_outbox_ready_idx on public.integration_outbox(destination,next_attempt_at,created_at) where status in ('pending','failed');
alter table public.integration_destinations enable row level security; alter table public.integration_outbox enable row level security; alter table public.integration_delivery_logs enable row level security;
create policy integration_destinations_manage on public.integration_destinations for select to authenticated using(public.wayne_has_permission('integrations.manage'));
create policy integration_outbox_manage on public.integration_outbox for select to authenticated using(public.wayne_has_permission('integrations.manage'));
create policy integration_delivery_logs_manage on public.integration_delivery_logs for select to authenticated using(public.wayne_has_permission('integrations.manage'));
create or replace function public.wayne_enqueue_hanafy_event(event_type_value text, data_value jsonb, occurred_at_value timestamptz default now()) returns uuid language plpgsql security definer set search_path='' as $$ declare event_value uuid; begin if not exists(select 1 from public.integration_destinations where id='hanafy' and active) then return null; end if; insert into public.integration_outbox(destination,event_type,occurred_at,payload) values('hanafy',event_type_value,occurred_at_value,jsonb_build_object('event_type',event_type_value,'occurred_at',occurred_at_value,'source','waynes-pos','business_id',(select business_id from public.integration_destinations where id='hanafy'),'version',1,'data',data_value)) returning event_id into event_value; return event_value; end; $$;
create or replace function public.wayne_outbox_from_customer_event() returns trigger language plpgsql security definer set search_path='' as $$ begin perform public.wayne_enqueue_hanafy_event(new.event_type,jsonb_build_object('customer_id',new.customer_id,'segment_id',new.segment_id,'metadata',new.metadata),new.occurred_at); return new; end; $$;
create trigger customer_events_enqueue_hanafy after insert on public.customer_events for each row execute function public.wayne_outbox_from_customer_event();
create or replace function public.wayne_claim_hanafy_outbox(worker_id text) returns jsonb language plpgsql security definer set search_path='' as $$ declare row_value public.integration_outbox%rowtype; begin select * into row_value from public.integration_outbox where destination='hanafy' and status in ('pending','failed') and next_attempt_at<=now() order by created_at for update skip locked limit 1; if not found then return null; end if; update public.integration_outbox set status='processing',attempts=attempts+1,lease_token=gen_random_uuid(),lease_expires_at=now()+interval '5 minutes',last_error=null where id=row_value.id returning * into row_value; return to_jsonb(row_value); end; $$;
create or replace function public.wayne_finish_hanafy_outbox(outbox_id uuid, token uuid, succeeded boolean, response_code_value integer default null, response_body_value text default null, error_value text default null) returns void language plpgsql security definer set search_path='' as $$ declare row_value public.integration_outbox%rowtype; begin select * into row_value from public.integration_outbox where id=outbox_id for update; if not found or row_value.status<>'processing' or row_value.lease_token is distinct from token or row_value.lease_expires_at<=now() then raise exception 'Stale integration outbox lease' using errcode='40001'; end if; insert into public.integration_delivery_logs(outbox_id,attempt_number,request_status,response_code,response_body_truncated,error_message) values(row_value.id,row_value.attempts,case when succeeded then 'delivered' else 'failed' end,response_code_value,left(response_body_value,2000),left(error_value,2000)); update public.integration_outbox set status=case when succeeded then 'delivered' else 'failed' end,delivered_at=case when succeeded then now() else null end,next_attempt_at=case when succeeded then next_attempt_at else now()+least(interval '24 hours',interval '1 minute' * power(2,least(attempts,10))) end,last_error=case when succeeded then null else left(error_value,2000) end,lease_token=null,lease_expires_at=null where id=row_value.id; end; $$;
create or replace function public.wayne_replay_hanafy_outbox(outbox_id uuid) returns void language plpgsql security definer set search_path='' as $$ begin if not public.wayne_has_permission('integrations.manage') then raise exception 'Integration management permission required' using errcode='42501'; end if; update public.integration_outbox set status='pending',next_attempt_at=now(),lease_token=null,lease_expires_at=null,last_error=null where id=outbox_id and destination='hanafy' and status in ('failed','delivered'); if not found then raise exception 'Replayable integration event not found' using errcode='P0002'; end if; end; $$;
revoke all on function public.wayne_enqueue_hanafy_event(text,jsonb,timestamptz),public.wayne_outbox_from_customer_event(),public.wayne_claim_hanafy_outbox(text),public.wayne_finish_hanafy_outbox(uuid,uuid,boolean,integer,text,text) from public,anon,authenticated;
revoke all on function public.wayne_replay_hanafy_outbox(uuid) from public; grant execute on function public.wayne_replay_hanafy_outbox(uuid) to authenticated;

create or replace function public.wayne_customer_hanafy_properties(target_customer_id uuid) returns jsonb language sql stable security definer set search_path='' as $$ select jsonb_build_object('customer_id',customer.id,'first_name',customer.first_name,'last_name',customer.last_name,'phone',customer.phone_normalized,'email',customer.email_normalized,'sms_marketing_opt_in',customer.sms_marketing_opt_in,'email_marketing_opt_in',customer.email_marketing_opt_in,'order_count',customer.order_count,'lifetime_spend_cents',customer.lifetime_spend_cents,'average_order_value_cents',customer.average_order_value_cents,'last_order_at',customer.last_order_at,'segments',coalesce((select jsonb_agg(jsonb_build_object('segment_id',segment.id,'name',segment.name,'entered_at',membership.entered_at,'exited_at',membership.exited_at,'active',membership.active) order by segment.name) from public.customer_segment_memberships membership join public.customer_segments segment on segment.id=membership.segment_id where membership.customer_id=customer.id and membership.active),'[]'::jsonb)) from public.customers customer where customer.id=target_customer_id; $$;
create or replace function public.wayne_enqueue_hanafy_event(event_type_value text, data_value jsonb, occurred_at_value timestamptz default now()) returns uuid language plpgsql security definer set search_path='' as $$ declare event_value uuid:=gen_random_uuid(); destination_row public.integration_destinations%rowtype; begin select * into destination_row from public.integration_destinations where id='hanafy' and active; if not found then return null; end if; insert into public.integration_outbox(event_id,destination,event_type,occurred_at,payload) values(event_value,'hanafy',event_type_value,occurred_at_value,jsonb_build_object('event_id',event_value,'event_type',event_type_value,'occurred_at',occurred_at_value,'source','waynes-pos','business_id',destination_row.business_id,'version',1,'data',data_value)); return event_value; end; $$;
create or replace function public.wayne_outbox_from_customer_event() returns trigger language plpgsql security definer set search_path='' as $$ begin perform public.wayne_enqueue_hanafy_event(new.event_type,coalesce(public.wayne_customer_hanafy_properties(new.customer_id),'{}'::jsonb)||jsonb_build_object('segment_id',new.segment_id,'event_metadata',new.metadata),new.occurred_at); return new; end; $$;
create or replace function public.wayne_outbox_from_customer_change() returns trigger language plpgsql security definer set search_path='' as $$ declare type_value text; begin type_value:=case when tg_op='INSERT' then 'customer.created' when old.sms_marketing_opt_in is distinct from new.sms_marketing_opt_in or old.email_marketing_opt_in is distinct from new.email_marketing_opt_in then 'customer.consent.changed' else 'customer.updated' end; perform public.wayne_enqueue_hanafy_event(type_value,public.wayne_customer_hanafy_properties(new.id),now()); return new; end; $$;
create trigger customers_enqueue_hanafy after insert or update of first_name,last_name,phone_normalized,email_normalized,sms_marketing_opt_in,email_marketing_opt_in on public.customers for each row execute function public.wayne_outbox_from_customer_change();
create or replace function public.wayne_outbox_from_order_change() returns trigger language plpgsql security definer set search_path='' as $$ declare type_value text; begin type_value:=case when tg_op='INSERT' then 'order.created' when new.status='completed' and old.status is distinct from new.status then 'order.completed' when new.status='cancelled' and old.status is distinct from new.status then 'order.cancelled' when new.payment_status='paid' and old.payment_status is distinct from new.payment_status then 'order.paid' else null end; if type_value is not null then perform public.wayne_enqueue_hanafy_event(type_value,jsonb_build_object('order_id',new.id,'order_number',new.order_number,'customer_id',new.customer_id,'status',new.status,'payment_status',new.payment_status,'total_cents',new.total_cents,'source',new.source,'fulfillment_type',new.fulfillment_type),coalesce(new.placed_at,now())); end if; return new; end; $$;
create trigger orders_enqueue_hanafy after insert or update of status,payment_status on public.orders for each row execute function public.wayne_outbox_from_order_change();
create or replace function public.wayne_configure_hanafy_integration(payload jsonb) returns void language plpgsql security definer set search_path='' as $$ begin if not public.wayne_has_permission('integrations.manage') then raise exception 'Integration management permission required' using errcode='42501'; end if; if coalesce(payload->>'endpoint_url','') !~ '^https://' or char_length(coalesce(payload->>'signing_secret',''))<32 then raise exception 'A HTTPS endpoint and 32-character signing secret are required' using errcode='22023'; end if; insert into public.integration_destinations(id,endpoint_url,business_id,signing_secret,previous_signing_secret,previous_secret_expires_at,active) values('hanafy',payload->>'endpoint_url',coalesce(nullif(payload->>'business_id',''),'waynes-pizza'),payload->>'signing_secret',nullif(payload->>'previous_signing_secret',''),nullif(payload->>'previous_secret_expires_at','')::timestamptz,coalesce((payload->>'active')::boolean,true)) on conflict(id) do update set endpoint_url=excluded.endpoint_url,business_id=excluded.business_id,previous_signing_secret=case when public.integration_destinations.signing_secret is distinct from excluded.signing_secret then public.integration_destinations.signing_secret else public.integration_destinations.previous_signing_secret end,previous_secret_expires_at=case when public.integration_destinations.signing_secret is distinct from excluded.signing_secret then now()+interval '7 days' else excluded.previous_secret_expires_at end,signing_secret=excluded.signing_secret,active=excluded.active,updated_at=now(); end; $$;
create or replace function public.wayne_admin_hanafy_integration() returns jsonb language plpgsql stable security definer set search_path='' as $$ begin if not public.wayne_has_permission('integrations.manage') then raise exception 'Integration management permission required' using errcode='42501'; end if; return jsonb_build_object('destination',(select jsonb_build_object('configured',true,'endpoint_url',endpoint_url,'business_id',business_id,'active',active,'secret_rotates_until',previous_secret_expires_at,'updated_at',updated_at) from public.integration_destinations where id='hanafy'),'counts',jsonb_build_object('pending',(select count(*) from public.integration_outbox where status='pending'),'processing',(select count(*) from public.integration_outbox where status='processing'),'failed',(select count(*) from public.integration_outbox where status='failed'),'delivered',(select count(*) from public.integration_outbox where status='delivered')),'events',coalesce((select jsonb_agg(jsonb_build_object('id',id,'event_id',event_id,'event_type',event_type,'status',status,'attempts',attempts,'last_error',last_error,'created_at',created_at,'delivered_at',delivered_at) order by created_at desc) from (select * from public.integration_outbox order by created_at desc limit 50) event_row),'[]'::jsonb)); end; $$;
revoke all on function public.wayne_customer_hanafy_properties(uuid),public.wayne_outbox_from_customer_change(),public.wayne_outbox_from_order_change(),public.wayne_configure_hanafy_integration(jsonb),public.wayne_admin_hanafy_integration() from public; grant execute on function public.wayne_configure_hanafy_integration(jsonb),public.wayne_admin_hanafy_integration() to authenticated;
